def _normalize_behaviour(behaviour) -> str:
    name = str(getattr(behaviour, "value", behaviour)).lower()
    if name == "confess":
        return "confessing"
    return name

def render_ascii_lines(grid) -> list[str]:
    """Render a 2D grid of (r, g, b, char) tuples into a list of ANSI TrueColor lines."""
    lines = []
    for row in grid:
        row_chars = []
        for r, g, b, c in row:
            if c == " ":
                row_chars.append(" ")
            else:
                row_chars.append(f"\033[38;2;{r};{g};{b}m{c}")
        lines.append("".join(row_chars) + "\033[0m")
    return lines

def render_ascii_grid(grid) -> str:
    """Render a 2D grid of (r, g, b, char) tuples into ANSI TrueColor text."""
    return "\n".join(render_ascii_lines(grid))

