# Pre-rendered static ANSI string portraits
PORTRAIT_LINES = {
    k: render_ascii_lines(v) for k, v in PORTRAIT_GRIDS.items()
}
COMPACT_PORTRAIT_LINES = {
    k: render_ascii_lines(v) for k, v in COMPACT_PORTRAIT_GRIDS.items()
}
PORTRAITS = {
    k: "\n".join(v) for k, v in PORTRAIT_LINES.items()
}

def get_portrait_lines(behaviour: str, compact: bool = False) -> list[str]:
    """Return the list of static TrueColor ASCII portrait lines for Marcus Webb."""
    name = _normalize_behaviour(behaviour)
    source = COMPACT_PORTRAIT_LINES if compact else PORTRAIT_LINES
    return source.get(name) or source.get("cooperative")

def get_portrait(behaviour: str, compact: bool = False) -> str:
    """Return the static TrueColor ASCII portrait string for Marcus Webb."""
    return "\n".join(get_portrait_lines(behaviour, compact=compact))

def show_portrait(behaviour: str, compact: bool = False):
    """Print the static TrueColor ASCII portrait for Marcus Webb."""
    art = get_portrait(behaviour, compact=compact)
    if art:
        print(f"\n{art}")

def set_portrait_style(style: str):
    pass  # Fine ASCII is always used

def get_morph_frames(from_behaviour: str, to_behaviour: str, frames: int = 10, compact: bool = False):
    """Yield 2D grids representing intermediate morph frames from from_behaviour to to_behaviour."""
    from_name = _normalize_behaviour(from_behaviour)
    to_name = _normalize_behaviour(to_behaviour)
    source = COMPACT_PORTRAIT_GRIDS if compact else PORTRAIT_GRIDS
    grid_a = source.get(from_name) or source.get("cooperative")
    grid_b = source.get(to_name) or source.get("cooperative")
    if not grid_a or not grid_b or from_name == to_name:
        yield grid_b
        return
    height = len(grid_a)
    width = len(grid_a[0])
    for f in range(1, frames + 1):
        t = f / frames
        t_eased = (1.0 - math.cos(t * math.pi)) / 2.0
        frame = []
        for y in range(height):
            row = []
            row_a = grid_a[y]
            row_b = grid_b[y]
            for x in range(width):
                ra, ga, ba, ca = row_a[x]
                rb, gb, bb, cb = row_b[x]
                r = int((1.0 - t_eased) * ra + t_eased * rb)
                g = int((1.0 - t_eased) * ga + t_eased * gb)
                b = int((1.0 - t_eased) * ba + t_eased * bb)
                threshold = BAYER_8X8[y % 8][x % 8]
                char = cb if t_eased >= threshold else ca
                row.append((r, g, b, char))
            frame.append(row)
        yield frame

async def morph_portrait(from_behaviour: str, to_behaviour: str, frames: int = 10, delay: float = 0.035, compact: bool = False):
    """Smoothly in-place cross-dissolve between two fine ASCII portraits using Bayer dithering."""
    from_name = _normalize_behaviour(from_behaviour)
    to_name = _normalize_behaviour(to_behaviour)

    if not sys.stdout.isatty():
        show_portrait(to_name, compact=compact)
        return

    source = COMPACT_PORTRAIT_GRIDS if compact else PORTRAIT_GRIDS
    grid_a = source.get(from_name) or source.get("cooperative")
    grid_b = source.get(to_name) or source.get("cooperative")

    if not grid_a or not grid_b or from_name == to_name:
        show_portrait(to_name, compact=compact)
        return

    height = len(grid_a)
    for frame in get_morph_frames(from_behaviour, to_behaviour, frames=frames, compact=compact):
        sys.stdout.write(f"\033[{height}A\r")
        sys.stdout.flush()
        sys.stdout.write(render_ascii_grid(frame) + "\n")
        sys.stdout.flush()
        await asyncio.sleep(delay)
